import type { NhsoCell } from '@backoffice/contracts';

/**
 * ติดตามกองทุนย่อย FDH: the REP and STM parsers, ported line for line from the legacy `FdhRepParser.php` and
 * `FdhStmParser.php` (same columns, same skipped rows, same messages). Parity is pinned by `fixtures/fdh-legacy.json`,
 * generated by running the PHP parsers.
 */
export type FdhSheets = Readonly<Record<string, readonly (readonly NhsoCell[] | null | undefined)[]>>;
type Row = readonly NhsoCell[];
type Table = readonly (Row | null | undefined)[];

export type FdhRepCase = {
  rep_no: string; tran_id: string; hn: string; an: string; pid: string; name: string; ptype: string; visit_date: string; net: number;
  error_code: string; main_fund: string; sub_fund: string; right: string; seq: string; pay_mode: string; charge: number;
};
export type FdhDeny = { tran_id: string; fund: string; code: string; category: string; qty: number; deny: string };
export type FdhDrug = { tran_id: string; icode: string; tmt: string; name: string; type: string; qty: number; claim: number; paid: number; error_code: string };
export type FdhRep = { type: 'rep'; doc_no: string; hcode: string; hname: string; report_date: string; cases: FdhRepCase[]; denies: FdhDeny[]; drugs: FdhDrug[] };
export const FDH_MONEY_KEYS = ['op', 'ip_calc', 'ip_paid', 'hc', 'hc_drug', 'ae', 'ae_drug', 'inst', 'dmis_calc', 'dmis_paid', 'dmis_drug', 'palliative', 'dmishd', 'pp', 'fs', 'opbkk', 'total'] as const;
export type FdhMoneyKey = (typeof FDH_MONEY_KEYS)[number];
export type FdhStmRow = {
  kind: 'normal' | 'appeal' | 'd1'; rep_no: string; tran_id: string; hn: string; an: string; pid: string; name: string; visit_date: string;
  maininscl: string; charge: number; source: string; seq: string;
} & Record<FdhMoneyKey, number>;
export type FdhStm = { type: 'stm'; doc_no: string; hcode: string; period: string; report_date: string; rows: FdhStmRow[] };
export type FdhDocument = FdhRep | FdhStm;
export type FdhParseResult<T> = { ok: true; document: T } | { ok: false; message: string };

class Refused extends Error {}

/** PHP `trim`: only space, tab, newline, carriage return, NUL and vertical tab (not NBSP, unlike `String.trim`). */
const PHP_SPACE = new Set([' ', '\t', '\n', '\r', '\0', '\v']);
function phpTrim(s: string): string {
  let start = 0;
  let end = s.length;
  while (start < end && PHP_SPACE.has(s[start]!)) start++;
  while (end > start && PHP_SPACE.has(s[end - 1]!)) end--;
  return s.slice(start, end);
}
/** PHP `(string)` of a cell: floats with 14 significant digits, true → "1", false/null → "". */
function phpString(value: NhsoCell | undefined): string {
  if (value === null || value === undefined || value === false) return '';
  if (value === true) return '1';
  if (typeof value === 'number') return Number.isInteger(value) && Math.abs(value) < 1e15 ? String(value) : String(Number(value.toPrecision(14)));
  return value;
}

/** `FdhRepParser::str`: a cell as text; whole numbers without decimals (SEQ/HN that Excel kept as numbers). */
export function fdhStr(value: NhsoCell | undefined): string {
  return phpTrim(phpString(value));
}

/** `FdhRepParser::num`: numbers as they are; text with "," or spaces when PHP `is_numeric`; anything else (e.g. "-") is 0. */
export function fdhNum(value: NhsoCell | undefined): number {
  if (typeof value === 'number') return value;
  const s = phpString(value).replace(/[, ]/g, '');
  return /^[ \t\n\r\v\f]*[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?[ \t\n\r\v\f]*$/.test(s) ? Number(s) : 0;
}

/** `FdhRepParser::isoDate`: "dd/mm/yyyy[ hh:mm:ss]" → YYYY-MM-DD; a year over 2400 (or `buddhist`) is พ.ศ. */
export function fdhIsoDate(value: string, buddhist: boolean): string {
  const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})/.exec(phpTrim(value));
  if (!m) return '';
  let year = Number(m[3]);
  if (buddhist || year > 2400) year -= 543;
  return `${String(year).padStart(4, '0')}-${m[2]!.padStart(2, '0')}-${m[1]!.padStart(2, '0')}`;
}

const norm = (value: NhsoCell | undefined) => phpTrim(phpString(value).replace(/\s+/gu, ' '));
const cell = (row: Row | null | undefined, index: number): NhsoCell | undefined => row?.[index];
const sheetNamed = (sheets: FdhSheets, name: string): Table | null => {
  for (const [key, table] of Object.entries(sheets)) if (phpTrim(key) === name && Array.isArray(table)) return table;
  return null;
};
/** PHP `pathinfo($fileName, PATHINFO_FILENAME)`. */
function fileStem(fileName: string): string {
  const base = fileName.split('/').pop() ?? '';
  const dot = base.lastIndexOf('.');
  return dot >= 0 ? base.slice(0, dot) : base;
}
function headText(table: Table, header: number): string {
  const parts: string[] = [];
  for (let r = 0; r < header; r++) for (const value of table[r] ?? []) { const s = fdhStr(value); if (s !== '') parts.push(s); }
  return parts.join(' | ');
}
function docNo(head: string, fileName: string): string {
  const doc = /เลขที่เอกสาร\s+(\S+)/u.exec(head)?.[1] ?? fileStem(fileName);
  if (!/^[A-Za-z0-9_]+$/.test(doc)) throw new Refused(`เลขที่เอกสารไม่ถูกต้อง: ${doc}`);
  return doc;
}
const hcodeOf = (head: string) => /โรงพยาบาล\s+(\d{5})/u.exec(head)?.[1] ?? '';
const reportDateOf = (head: string) => { const m = /ออกรายงานวันที่\s+(\d{1,2}\/\d{1,2}\/\d{4})/u.exec(head); return m ? fdhIsoDate(m[1]!, true) : ''; };
const attempt = <T>(run: () => T): FdhParseResult<T> => {
  try { return { ok: true, document: run() }; } catch (error) { if (error instanceof Refused) return { ok: false, message: error.message }; throw error; }
};

// ---------- REP ----------
const REP_REQUIRED: readonly (readonly [string, keyof FdhRepCase])[] = [
  ['REP No.', 'rep_no'], ['TRAN_ID', 'tran_id'], ['HN', 'hn'], ['AN', 'an'], ['PID', 'pid'], ['ชื่อ-สกุล', 'name'], ['ประเภทผู้ป่วย', 'ptype'],
  ['วันเข้ารักษา', 'visit_date'], ['ชดเชยสุทธิ', 'net'], ['Error Code', 'error_code'], ['กองทุนหลัก', 'main_fund'], ['กองทุนย่อย', 'sub_fund'],
  ['สิทธิหลัก', 'right'], ['SEQ NO', 'seq']
];
const REP_OPTIONAL: readonly (readonly [string, keyof FdhRepCase])[] = [['รูปแบบการจ่าย', 'pay_mode']];
const DRUG_COLUMNS: readonly (readonly [string, keyof FdhDrug])[] = [
  ['TRAN_ID', 'tran_id'], ['รหัสยา รพ.', 'icode'], ['TMT', 'tmt'], ['ชื่อการค้า', 'name'], ['ชนิดยา', 'type'], ['จำนวน', 'qty'],
  ['รวมเงินที่ขอเบิก', 'claim'], ['รวมชดเชย', 'paid'], ['Error Code', 'error_code']
];

function repHeaderRow(table: Table): number | null {
  for (let i = 0; i < Math.min(30, table.length); i++) if (norm(cell(table[i], 0)) === 'REP No.') return i;
  return null;
}

/** `FdhRepParser::isRep`: a `Detail` sheet with a "REP No." header in its first 30 rows. */
export function isFdhRep(sheets: FdhSheets): boolean {
  const detail = sheetNamed(sheets, 'Detail');
  return detail !== null && repHeaderRow(detail) !== null;
}

function chargeColumn(table: Table, header: number): number | null {
  for (let r = header + 1; r <= header + 2; r++) {
    const row = table[r] ?? [];
    for (let i = 0; i < row.length; i++) if (norm(row[i]).startsWith('รวมยอดเรียกเก็บ')) return i;
  }
  return null;
}

function denies(table: Table | null): FdhDeny[] {
  if (table === null) return [];
  const header = table.findIndex((row) => norm(cell(row, 1)) === 'TRAN_ID' && norm(cell(row, 12)) === 'DENY');
  if (header < 0) return [];
  const out: FdhDeny[] = [];
  for (let r = header + 1; r < table.length; r++) {
    const row = table[r] ?? [];
    if (fdhStr(cell(row, 1)) === '') continue;
    out.push({ tran_id: fdhStr(cell(row, 1)), fund: fdhStr(cell(row, 8)), code: fdhStr(cell(row, 9)), category: fdhStr(cell(row, 10)), qty: fdhNum(cell(row, 11) ?? 0), deny: fdhStr(cell(row, 12)) });
  }
  return out;
}

function drugs(table: Table | null): FdhDrug[] {
  if (table === null) return [];
  let header: number | null = null;
  for (let i = 0; i < Math.min(30, table.length); i++) if (norm(cell(table[i], 1)) === 'TRAN_ID') { header = i; break; }
  if (header === null) return [];
  const columns: Partial<Record<keyof FdhDrug, number>> = {};
  for (const r of [header, header + 1]) {
    const row = table[r] ?? [];
    for (let i = 0; i < row.length; i++) {
      const n = norm(row[i]);
      for (const [head, field] of DRUG_COLUMNS) if (columns[field] === undefined && n !== '' && n.startsWith(head)) columns[field] = i;
    }
  }
  if (columns.tran_id === undefined || columns.icode === undefined || columns.paid === undefined) return [];
  const out: FdhDrug[] = [];
  for (let r = header + 2; r < table.length; r++) {
    const row = table[r] ?? [];
    const tran = fdhStr(cell(row, columns.tran_id));
    if (tran === '' || !/^\d+$/.test(tran)) continue;
    const drug = {} as Record<keyof FdhDrug, string | number>;
    for (const [, field] of DRUG_COLUMNS) {
      const at = columns[field];
      const value = at === undefined ? '' : (cell(row, at) ?? '');
      drug[field] = field === 'qty' || field === 'claim' || field === 'paid' ? fdhNum(value) : fdhStr(value);
    }
    out.push(drug as FdhDrug);
  }
  return out;
}

/** `FdhRepParser::parse`. */
export function parseFdhRep(sheets: FdhSheets, fileName: string): FdhParseResult<FdhRep> {
  return attempt(() => {
    const detail = sheetNamed(sheets, 'Detail');
    const header = detail === null ? null : repHeaderRow(detail);
    if (detail === null || header === null) throw new Refused('ไม่ใช่ไฟล์ REP ของ FDH (ไม่พบชีต Detail ที่มีหัวตาราง REP No.)');
    const columns = new Map<string, number>();
    (detail[header] ?? []).forEach((name, i) => { const n = norm(name); if (n !== '' && !columns.has(n)) columns.set(n, i); });
    const missing = REP_REQUIRED.map(([head]) => head).filter((head) => !columns.has(head));
    if (missing.length) throw new Refused(`ไฟล์ REP ไม่มีคอลัมน์: ${missing.join(', ')}`);
    const charge = chargeColumn(detail, header);
    const at = (head: string) => columns.get(head)!;
    const cases: FdhRepCase[] = [];
    for (let r = header + 1; r < detail.length; r++) {
      const row = detail[r] ?? [];
      if (fdhStr(cell(row, at('TRAN_ID'))) === '' || fdhStr(cell(row, at('REP No.'))) === '') continue;
      const found = {} as Record<keyof FdhRepCase, string | number>;
      for (const [head, field] of [...REP_REQUIRED, ...REP_OPTIONAL]) found[field] = fdhStr(columns.has(head) ? (cell(row, at(head)) ?? '') : '');
      found.net = fdhNum(cell(row, at('ชดเชยสุทธิ')) ?? 0);
      found.charge = charge === null ? 0 : fdhNum(cell(row, charge) ?? 0);
      found.visit_date = fdhIsoDate(found.visit_date as string, false);
      cases.push(found as FdhRepCase);
    }
    const head = headText(detail, header);
    return {
      type: 'rep' as const, doc_no: docNo(head, fileName), hcode: hcodeOf(head),
      hname: phpTrim(/โรงพยาบาล\s+\d{5}\s+([^|]+)/u.exec(head)?.[1] ?? ''), report_date: reportDateOf(head), cases,
      denies: denies(sheetNamed(sheets, 'Data DENY')), drugs: drugs(sheetNamed(sheets, 'Data Drug'))
    };
  });
}

// ---------- STM ----------
const STM_MONEY: Readonly<Record<FdhMoneyKey, number>> = {
  op: 21, ip_calc: 22, ip_paid: 23, hc: 24, hc_drug: 25, ae: 26, ae_drug: 27, inst: 28, dmis_calc: 29, dmis_paid: 30, dmis_drug: 31,
  palliative: 32, dmishd: 33, pp: 34, fs: 35, opbkk: 36, total: 37
};
const STM_EXPECT: readonly (readonly [number, number, string])[] = [
  [0, 0, 'REP'], [0, 2, 'TRAN_ID'], [0, 11, 'เรียกเก็บ'], [0, 37, 'ยอดชดเชยทั้งสิ้น'], [0, 41, 'SEQ NO'],
  [1, 21, 'OP'], [1, 22, 'IP'], [1, 24, 'HC'], [1, 26, 'AE'], [1, 28, 'INST'], [1, 29, 'DMIS'],
  [1, 32, 'Palliative care'], [1, 33, 'DMISHD'], [1, 34, 'PP'], [1, 35, 'FS'], [1, 36, 'OPBKK']
];
type DetailSheet = { kind: FdhStmRow['kind']; table: Table; header: number; name: string };

function stmDetailSheets(sheets: FdhSheets): DetailSheet[] {
  const out: DetailSheet[] = [];
  for (const [key, table] of Object.entries(sheets)) {
    const name = phpTrim(key);
    if (!name.startsWith('รายละเอียด') || !Array.isArray(table)) continue;
    let header: number | null = null;
    for (let i = 0; i < Math.min(30, table.length); i++) if (norm(cell(table[i], 0)) === 'REP') { header = i; break; }
    if (header === null) continue;
    out.push({ kind: name.includes('อุทธรณ์') ? 'appeal' : name.includes('D1') ? 'd1' : 'normal', table, header, name });
  }
  return out;
}

/** `FdhStmParser::isStm`: a sheet named "รายละเอียด…" with a "REP" header in its first 30 rows. */
export function isFdhStm(sheets: FdhSheets): boolean {
  return stmDetailSheets(sheets).length > 0;
}

function columnName(index: number): string {
  let s = '';
  for (let i = index + 1; i > 0; i = Math.floor((i - 1) / 26)) s = String.fromCharCode(65 + ((i - 1) % 26)) + s;
  return s;
}

function checkStmHeader({ table, header, name }: DetailSheet): void {
  for (const [dr, column, text] of STM_EXPECT) {
    const got = norm(cell(table[header + dr], column) ?? '');
    if (got.toLowerCase() !== text.toLowerCase()) throw new Refused(`หัวตาราง STM ชีต "${name}" ไม่ตรงรูปแบบ: คอลัมน์ ${columnName(column)} ควรเป็น "${text}" แต่พบ "${got}"`);
  }
}

function stmPeriod(sheets: FdhSheets): string {
  for (const [key, table] of Object.entries(sheets)) {
    if (!phpTrim(key).startsWith('รายงานสรุป') || !Array.isArray(table)) continue;
    let seen = false;
    for (const row of table) {
      const a = norm(cell(row, 0) ?? '');
      if (a === 'งวด') seen = true;
      else if (seen && /^\d{4}_/.test(a)) return a;
    }
  }
  return '';
}

/** `FdhStmParser::parse`. */
export function parseFdhStm(sheets: FdhSheets, fileName: string): FdhParseResult<FdhStm> {
  return attempt(() => {
    const details = stmDetailSheets(sheets);
    if (!details.length) throw new Refused('ไม่ใช่ไฟล์ STM ของ FDH (ไม่พบชีต "รายละเอียด" ที่มีหัวตาราง REP)');
    const rows: FdhStmRow[] = [];
    let head = '';
    for (const sheet of details) {
      checkStmHeader(sheet);
      if (head === '') head = headText(sheet.table, sheet.header);
      for (let r = sheet.header + 3; r < sheet.table.length; r++) {
        const row = sheet.table[r] ?? [];
        const seq = fdhStr(cell(row, 41) ?? '');
        const tran = fdhStr(cell(row, 2) ?? '');
        // A data row has a numeric REP: skips the next block's repeated header, the รวม row and the legend at the end.
        if ((seq === '' && tran === '') || !/^\d+$/.test(fdhStr(cell(row, 0) ?? ''))) continue;
        const out = {
          kind: sheet.kind, rep_no: fdhStr(cell(row, 0) ?? ''), tran_id: tran, hn: fdhStr(cell(row, 3) ?? ''), an: fdhStr(cell(row, 4) ?? ''),
          pid: fdhStr(cell(row, 5) ?? ''), name: fdhStr(cell(row, 6) ?? ''), visit_date: fdhIsoDate(fdhStr(cell(row, 7) ?? ''), false),
          maininscl: fdhStr(cell(row, 9) ?? ''), charge: fdhNum(cell(row, 11) ?? 0)
        } as FdhStmRow;
        for (const key of FDH_MONEY_KEYS) out[key] = fdhNum(cell(row, STM_MONEY[key]) ?? 0);
        out.source = fdhStr(cell(row, 40) ?? '');
        out.seq = seq;
        rows.push(out);
      }
    }
    return { type: 'stm' as const, doc_no: docNo(head, fileName), hcode: hcodeOf(head), period: stmPeriod(sheets), report_date: reportDateOf(head), rows };
  });
}

/** What the legacy upload page did: REP if it looks like REP, else STM if it looks like STM, else refused. */
export function parseFdhDocument(sheets: FdhSheets, fileName: string): FdhParseResult<FdhDocument> {
  if (isFdhRep(sheets)) return parseFdhRep(sheets, fileName);
  if (isFdhStm(sheets)) return parseFdhStm(sheets, fileName);
  return { ok: false, message: 'ไฟล์นี้ไม่ใช่ REP หรือ STM ของ FDH' };
}
